import {McpServer} from '@modelcontextprotocol/sdk/server/mcp.js';
import {WebStandardStreamableHTTPServerTransport} from '@modelcontextprotocol/sdk/server/webStandardStreamableHttp.js';
import {z} from 'zod';
import {load,act} from './store.js';
import {mcpView} from './engine.js';
export async function handleMcp(req,env){
const url=new URL(req.url);const origin=req.headers.get('origin');if(origin&&origin!==url.origin)return new Response('Forbidden origin',{status:403});
const user=req.headers.get('oai-authenticated-user-id');
if(req.method==='POST'){let p;try{p=await req.clone().json();}catch{return Response.json({jsonrpc:'2.0',id:null,error:{code:-32700,message:'Parse error'}},{status:400});}if(p?.method==='tools/call'&&!user)return new Response('Sign in required',{status:401});}
const server=new McpServer({name:'unclaimed-robot-shop',version:'2.0.0'},{instructions:'Play the authored Chinese narrative game. Read state, choose one legal choice ID with its revision. Linear passages are bundled automatically until a real choice or ending. No full-history replay is needed. Web and MCP share the same saved playthrough for your authenticated account. Do not restart without the player asking.'});
const output=v=>({content:[{type:'text',text:JSON.stringify(v)}],structuredContent:v});
const error=e=>({content:[{type:'text',text:e.message||'操作失败'}],isError:true});
server.registerTool('get_game_state',{title:'读取当前游戏',description:'Read the current saved scene, legal choice IDs, resources and preparation status. Repeated reads do not advance the story. Does not reveal future branches.',inputSchema:{},annotations:{readOnlyHint:true,openWorldHint:false}},async()=>{try{if(!user)throw Error('请先登录');return output(mcpView(await load(env.DB,user)));}catch(e){return error(e);}});
server.registerTool('choose_game_action',{title:'作出游戏选择',description:'Commit one currently available choice, then include consecutive non-branching story passages in the same reply. Stops at the next actual choice or ending. Requires the latest revision; stale/repeated choices are rejected. Shares the web save.',inputSchema:{choice_id:z.string(),revision:z.number().int().nonnegative()},annotations:{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false}},async({choice_id,revision})=>{try{if(!user)throw Error('请先登录');return output(mcpView(await act(env.DB,user,{choice:choice_id,revision},'choose',true)));}catch(e){return error(e);}});
server.registerTool('restart_game',{title:'归档并重新开始',description:'Archive the existing playthrough and begin again only when the player explicitly asks. confirmation must be true; provide the latest revision.',inputSchema:{revision:z.number().int().nonnegative(),confirmation:z.literal(true)},annotations:{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false}},async({revision,confirmation})=>{try{if(!user)throw Error('请先登录');return output(mcpView(await act(env.DB,user,{revision,confirm:confirmation},'restart')));}catch(e){return error(e);}});
server.registerTool('start_next_story',{title:'进入第二部或河西日常',description:'Archive the current playthrough, then begin the follow-up. Use route=continue to inherit the current completed first part, or the most recently completed first-part survival record among the last 10 archives. Never assume a demo profile is the player’s history. Explicitly requested standalone trials may choose stay, move or mobile. Requires confirmation=true; never start or overwrite progress without player permission.',inputSchema:{revision:z.number().int().nonnegative(),route:z.enum(['continue','stay','move','mobile']),confirmation:z.literal(true)},annotations:{readOnlyHint:false,destructiveHint:false,idempotentHint:false,openWorldHint:false}},async({revision,route,confirmation})=>{try{if(!user)throw Error('请先登录');return output(mcpView(await act(env.DB,user,{revision,route,confirm:confirmation},'sequel')));}catch(e){return error(e);}});
const transport=new WebStandardStreamableHTTPServerTransport({sessionIdGenerator:undefined,enableJsonResponse:true,maxRequestBodySize:65536});
await server.connect(transport);try{return await transport.handleRequest(req);}finally{await server.close();}
}
